<template><view class="account-page feature-page members-page"><FeaturePageState :status="status" :error="error" @retry="load"/><template v-if="status==='ready'"><EmptyState v-if="!items.length" text="暂无会员，点击下方添加"/><view v-for="(member,index) in items" :key="member.id" class="member-card"><text class="member-index">会员{{index+1}}</text><view class="member-heading"><image v-if="member.avatarUrl" class="member-avatar" :src="member.avatarUrl" mode="aspectFill"/><view v-else class="member-avatar avatar-letter">{{member.name?.slice(0,1)}}</view><view class="member-information"><view class="member-name">{{member.name}}<text>{{member.badge||'未激活会员'}}</text></view><view class="member-meta">ID：{{member.displayId||member.id}}　年级：{{member.gradeLabel}}　性别：{{member.genderLabel}}</view></view></view><view class="member-benefit"><text class="benefit-title">陪练卡</text><view class="benefit-body"><view>训练：共{{member.training?.total ?? '—'}}时，已消耗{{member.training?.used ?? '—'}}时，剩余{{member.training?.remaining ?? '—'}}时</view></view><button @click="records(member,'training')">陪练反馈</button></view><view class="member-benefit"><text class="benefit-title">智习室</text><view class="benefit-body">{{member.selfStudyNote||'暂无记录'}}</view><button @click="records(member,'self-study')">智习反馈</button></view><view class="member-benefit"><text class="benefit-title">集训营</text><view class="benefit-body">{{member.campNote||'暂无记录'}}</view><button @click="records(member,'camp')">集训反馈</button></view><view class="member-benefit"><text class="benefit-title">备注</text><view class="benefit-body">{{member.remark||'暂无备注'}}</view></view><view class="member-actions"><button @click="openEditor(member)"><image src="/static/common/icon-edit.png" mode="aspectFit"/>编辑</button><button @click="openActivation(member)"><image src="/static/common/icon-activate.png" mode="aspectFit"/>激活</button><button class="orders-link" @click="records(member,'orders')">查看订单</button></view></view><button v-if="hasMore" class="secondary" :disabled="loadingMore" @click="more">{{loadingMore?'加载中…':'加载更多'}}</button><text v-if="moreError" class="account-error">{{moreError}}</text><view class="account-bottom"><button class="primary" @click="openEditor(null)">添加会员</button></view></template><view v-if="editorOpen" class="feature-mask" @click.self="closeEditor"><view class="feature-sheet"><view class="panel-heading">{{editingId?'编辑会员':'添加会员'}}<button class="close-feature" :disabled="saving||uploading" aria-label="关闭会员编辑" @click="closeEditor"><image src="/static/common/icon-close.png" mode="aspectFit"/></button></view><button class="avatar-upload" :disabled="saving||uploading" @click="chooseAvatar"><image v-if="avatarPreview" :src="avatarPreview" mode="aspectFill"/><image v-else src="/static/common/icon-image.png" mode="aspectFit"/><text>{{uploading?'处理中…':'点击上传头像'}}</text></button><view class="account-row"><text class="account-label">会员姓名</text><input v-model="draft.name" class="account-input" :disabled="saving" :maxlength="24" placeholder="请输入"/></view><view class="account-row"><text class="account-label">会员年级</text><picker :range="dictionaries.grades" range-key="label" :value="gradeIndex" :disabled="saving" @change="draft.gradeCode=dictionaries.grades[$event.detail.value].code"><view class="member-picker">{{gradeLabel||'请选择'}}<image src="/static/common/icon-chevron-right.png" mode="aspectFit"/></view></picker></view><view class="account-row"><text class="account-label">会员性别</text><picker :range="dictionaries.genders" range-key="label" :value="genderIndex" :disabled="saving" @change="draft.genderCode=dictionaries.genders[$event.detail.value].code"><view class="member-picker">{{genderLabel||'请选择'}}<image src="/static/common/icon-chevron-right.png" mode="aspectFit"/></view></picker></view><text v-if="editorError" class="account-error">{{editorError}}</text><button class="primary" :disabled="saving||uploading" @click="save">{{saving?'保存中…':'确定'}}</button></view></view><view v-if="activationMember" class="feature-mask" @click.self="closeActivation"><view class="feature-sheet"><view class="panel-heading">激活会员<button class="close-feature" :disabled="activating" aria-label="关闭激活" @click="closeActivation"><image src="/static/common/icon-close.png" mode="aspectFit"/></button></view><text class="feature-note">受益会员：{{activationMember.name}}（{{activationMember.displayId}}）</text><input :value="activationCode" class="account-input" :disabled="activating" :maxlength="100" placeholder="请输入激活码" @input="changeCode"/><view v-if="activationPreview" class="feature-note">即将为{{activationPreview.memberName||activationMember.name}}激活：{{activationPreview.levelName||activationPreview.targetLabel||activationPreview.targetId}}</view><text v-if="activationError" class="account-error">{{activationError}}</text><button class="primary" :disabled="activating||!activationCode.trim()" @click="activate">{{activating?'处理中…':activationPreview?'确认激活':'校验激活码'}}</button></view></view></view></template>
<script setup>
import {ref,computed,watch} from 'vue'
import {onUnload} from '@dcloudio/uni-app'
import {config} from '../../config'
import {useAuth} from '../../composables/useAuth'
import {useAsyncPage} from '../../composables/useAsyncPage'
import {getFamilyMembers,getMemberDictionaries,saveFamilyMember,previewMemberActivation,activateFamilyMember} from '../../services/members'
import {uploadProfileImage} from '../../services/profile'
import FeaturePageState from '../../components/FeaturePageState.vue'
import EmptyState from '../../components/EmptyState.vue'
useAuth();const isMock=config.useMock,items=ref([]),hasMore=ref(false),loadingMore=ref(false),moreError=ref(''),dictionaries=ref({grades:[],genders:[]}),editorOpen=ref(false),editingId=ref(''),draft=ref({}),avatarPreview=ref(''),editorError=ref(''),saving=ref(false),uploading=ref(false),activationMember=ref(null),activationCode=ref(''),activationPreview=ref(null),activationError=ref(''),activating=ref(false)
let cursor=null,epoch=0,editorEpoch=0,activationEpoch=0,active=true,activationKey='',memberSaveKey='',memberSavePayload=''
const {data,status,error,load}=useAsyncPage(async()=>{const [result,options]=await Promise.all([getFamilyMembers(),getMemberDictionaries()]);if(!Array.isArray(options?.grades)||!Array.isArray(options.genders))throw new Error('会员字典配置异常');return {...result,dictionaries:options}})
watch(status,value=>{if(value==='loading'){++epoch;loadingMore.value=false;moreError.value=''}})
watch(data,result=>{if(result){items.value=result.items;hasMore.value=result.hasMore;cursor=result.nextCursor;dictionaries.value=result.dictionaries}})
const gradeIndex=computed(()=>Math.max(0,dictionaries.value.grades.findIndex(item=>item.code===draft.value.gradeCode))),genderIndex=computed(()=>Math.max(0,dictionaries.value.genders.findIndex(item=>item.code===draft.value.genderCode)))
const gradeLabel=computed(()=>dictionaries.value.grades.find(item=>item.code===draft.value.gradeCode)?.label),genderLabel=computed(()=>dictionaries.value.genders.find(item=>item.code===draft.value.genderCode)?.label)
function openEditor(member){++editorEpoch;memberSaveKey='';memberSavePayload='';editingId.value=member?.id||'';draft.value={name:member?.name||'',gradeCode:member?.gradeCode||'',genderCode:member?.genderCode||'',version:member?.version,avatarAssetId:''};avatarPreview.value=member?.avatarUrl||'';editorError.value='';editorOpen.value=true}
function closeEditor(){if(saving.value||uploading.value)return;++editorEpoch;editorOpen.value=false}
async function chooseAvatar(){if(saving.value||uploading.value)return;const current=editorEpoch;uploading.value=true;editorError.value='';try{const chosen=await new Promise(resolve=>uni.chooseImage({count:1,sourceType:['album'],success:resolve,fail:()=>resolve(null)}));if(!chosen||!active||current!==editorEpoch)return;const result=await uploadProfileImage({path:chosen.tempFilePaths[0],size:chosen.tempFiles[0].size},'member-avatar');if(active&&current===editorEpoch){draft.value.avatarAssetId=result.assetId;avatarPreview.value=result.previewUrl}}catch(reason){if(active&&current===editorEpoch)editorError.value=reason.message}finally{if(active&&current===editorEpoch)uploading.value=false}}
async function save(){if(saving.value||uploading.value)return;const current=editorEpoch;saving.value=true;editorError.value='';try{const fingerprint=JSON.stringify(draft.value);if(fingerprint!==memberSavePayload){memberSavePayload=fingerprint;memberSaveKey='member-'+Date.now()+'-'+Math.random().toString(36).slice(2)}await saveFamilyMember(editingId.value,{...draft.value,idempotencyKey:memberSaveKey});if(active&&current===editorEpoch){editorOpen.value=false;uni.showToast({title:'已保存',icon:'success'});await load()}}catch(reason){if(active&&current===editorEpoch)editorError.value=reason.message||'保存失败'}finally{if(active)saving.value=false}}
function openActivation(member){++activationEpoch;activationMember.value=member;activationCode.value='';activationPreview.value=null;activationError.value='';activationKey=''}
function closeActivation(){if(activating.value)return;++activationEpoch;activationMember.value=null}
function changeCode(event){activationCode.value=event.detail.value;activationPreview.value=null;activationKey='';activationError.value=''}
async function activate(){if(activating.value||!activationMember.value||!activationCode.value.trim())return;const current=activationEpoch;activating.value=true;activationError.value='';try{if(!activationPreview.value){const result=await previewMemberActivation(activationMember.value.id,activationCode.value);if(active&&current===activationEpoch){if(result.memberId!==activationMember.value.id||!result.targetId)throw new Error('激活预览身份异常');activationPreview.value=result}}else{if(!activationKey)activationKey=`member-activation-${Date.now()}-${Math.random().toString(36).slice(2)}`;await activateFamilyMember(activationMember.value.id,activationPreview.value,activationKey);if(active&&current===activationEpoch){activationMember.value=null;uni.showModal({title:'激活成功',content:'权益已更新，请在会员页面切换到对应会员查看。',showCancel:false});await load()}}}catch(reason){if(active&&current===activationEpoch)activationError.value=reason.message||'激活失败，请重试'}finally{if(active)activating.value=false}}
function records(member,kind){uni.navigateTo({url:`/pages/members/records?memberId=${encodeURIComponent(member.id)}&kind=${kind}`})}
async function more(){if(loadingMore.value||!hasMore.value)return;const current=epoch;loadingMore.value=true;try{const result=await getFamilyMembers(cursor);if(current===epoch){items.value=[...new Map([...items.value,...result.items].map(item=>[item.id,item])).values()];hasMore.value=result.hasMore;cursor=result.nextCursor}}catch(reason){if(current===epoch)moreError.value=reason.message}finally{if(current===epoch)loadingMore.value=false}}
onUnload(()=>{active=false;++epoch;++editorEpoch;++activationEpoch})
</script>
<style>@import '../../styles/account.css';@import '../../styles/exclusive.css';</style>
<style scoped>.member-card{position:relative;padding:34rpx 24rpx 28rpx;background:#343a5b;border-radius:24rpx;margin-bottom:24rpx}.member-index{position:absolute;right:0;top:0;background:#596381;border-radius:0 24rpx 0 24rpx;padding:4rpx 14rpx;font-size:calc(var(--feature-font,14px)*0.92857)}.member-heading{display:flex;gap:20rpx;align-items:center;margin-bottom:30rpx}.member-avatar{width:98rpx;height:98rpx;border-radius:50%;flex-shrink:0}.avatar-letter{display:flex;align-items:center;justify-content:center;background:#375682;color:#fff;font-size:calc(var(--feature-font,14px)*1.35714)}.member-information{flex:1;min-width:0}.member-name{font-size:calc(var(--feature-font,14px)*1.14286);font-weight:600;overflow-wrap:anywhere}.member-name text{display:inline-block;border-radius:30rpx;background:linear-gradient(90deg,#00baff,#3056ff);padding:4rpx 12rpx;margin-left:12rpx;font-size:calc(var(--feature-font,14px)*0.92857);font-weight:400}.member-meta{font-size:calc(var(--feature-font,14px)*0.92857);color:#a8b8d1;line-height:1.8;margin-top:12rpx;overflow-wrap:anywhere}.member-benefit{display:flex;border-radius:16rpx;background:#454d6e;margin-bottom:14rpx;overflow:hidden;min-height:96rpx}.benefit-title{width:2.5em;flex-shrink:0;background:#555e7b;display:flex;align-items:center;justify-content:center;padding:.6em .5em;line-height:1.3;font-size:calc(var(--feature-font,14px)*0.92857);word-break:break-all;color:#c1cce0}.benefit-body{flex:1;min-width:0;padding:18rpx;font-size:calc(var(--feature-font,14px)*0.92857);line-height:1.7;overflow-wrap:anywhere}.member-benefit button{width:2.5em;flex-shrink:0;background:#00b861;color:white;font-size:calc(var(--feature-font,14px)*0.92857);line-height:1.2;padding:.6em .5em;margin:0;border-radius:0;word-break:break-all;display:flex;align-items:center;justify-content:center}.member-actions{display:flex;align-items:center;gap:24rpx;margin-top:24rpx}.member-actions button{display:flex;align-items:center;gap:8rpx;padding:0;margin:0;background:none;color:#fff;font-size:calc(var(--feature-font,14px)*0.92857);line-height:1.8}.member-actions image{width:40rpx;height:40rpx}.member-actions .orders-link{margin-left:auto;background:linear-gradient(90deg,#00b7ff,#3157ff);border-radius:40rpx;padding:10rpx 24rpx}.avatar-upload{display:flex;flex-direction:column;align-items:center;gap:12rpx;margin:0 auto;background:none;color:#a7b8d3;font-size:calc(var(--feature-font,14px)*0.92857);line-height:1.7}.avatar-upload image{height:120rpx;width:120rpx;border-radius:50%}.feature-sheet picker{flex:1;min-width:0}.member-picker{height:80rpx;padding:0 22rpx;border-radius:40rpx;background:#464e70;display:flex;align-items:center;justify-content:space-between;font-size:calc(var(--feature-font,14px)*0.96429)}.member-picker image{height:28rpx;width:28rpx}</style>
